"""Execute the final notebook top to bottom on a fresh T4 and save it with all outputs (Batch 9, G3).
The notebook (notebook/rescue_router.ipynb, generated by notebook/build_notebook.py) is embedded below; outputs:
/kaggle/working/rescue_router_executed.ipynb (+ .html). Inputs: rr-bundle-b13 (Batch 13 data bundle), rr-fetch-data (generalist.ckpt)."""
import base64, subprocess, time
NB = ""
open('/kaggle/working/rescue_router.ipynb', 'wb').write(base64.b64decode(NB))
t = time.time()
r = subprocess.run('jupyter nbconvert --to notebook --execute --ExecutePreprocessor.timeout=-1 '
                   '--output rescue_router_executed.ipynb rescue_router.ipynb', shell=True, cwd='/kaggle/working',
                   capture_output=True, text=True)
print(r.stdout[-3000:], r.stderr[-3000:], 'rc', r.returncode, f'{(time.time() - t) / 60:.1f} min', flush=True)
subprocess.run('jupyter nbconvert --to html rescue_router_executed.ipynb', shell=True, cwd='/kaggle/working')
